const COLDSNAP_PROJECTS=[{id:"cpps-exhibit",category:"Interactive Installations",fit:["kiosk","game","museum","school","public"],type:"Museum Installation",title:"CPPS Earthquake Museum",featured:!0,shortDescription:"Exhibit framework, touchscreen mini-games and an escape game for a public earthquake training centre",description:"A public earthquake training centre in Switzerland where visitors learn, by playing, what an earthquake is and how to react. The technology behind it: 27 interactive stations across 3 spaces with 30+ touchscreen mini-games, designed with seismologists and university professors; a fleet of 30 kiosk tablets updated remotely; Escape With Wallis, an hour-long escape game through the exhibit; and the reservation and payment platform for schools, companies and public services. The centre also houses Europe's largest earthquake simulator.",icon:"\u{1F3DB}\uFE0F",thumbnail:"/assets/projects/cpps/cpps-4-thumb.webp",media:["/assets/projects/cpps/cpps-4.jpg","/assets/projects/cpps/cpps-1.jpg","/assets/projects/cpps/cpps-2.jpg","/assets/projects/cpps/cpps-3.jpg","/assets/projects/cpps/cpps-5.jpg"],alt:["Exhibition hall with wall screens, a long wooden table of interactive stations and a seismic cable installation","Exhibit corner with a wall touchscreen, Swiss seismic map and rock samples on a wooden counter","Touchscreen game 'The magnitude of an earthquake': a magnitude slider compares the 1964 Alaska quake with Switzerland","Touchscreen game 'How to locate an earthquake': seismometers placed on a map of the Alps to find the epicentre","Exhibition space with an illuminated landscape diorama, a wall touchscreen and a wooden house model"],stats:[{value:"30k",label:"visitors / year",fr:"visiteurs / an"},{value:"27",label:"interactive stations",fr:"stations interactives"},{value:"30+",label:"touchscreen mini-games",fr:"mini-jeux tactiles"}],tech:["Unity","Android","Docker","Firebase","Stripe","Kiosk UI"],features:["30+ touchscreen mini-games across 3 spaces and 27 stations","Fleet of 30 kiosked wall tablets, centrally configured and remotely updated","Escape With Wallis: hour-long escape game, 3,000+ sessions completed","Reservation and payment platform, 50,000 users a year","Designed with seismology experts and university professors","Multi-language content"],links:[{label:"See it on Valbilon",labelFr:"Voir le projet sur Valbilon",href:"https://www.valbilon.com/projects/cpps-exhibit",icon:"fa-external-link"}],fr:{alt:["Salle d'exposition avec \xE9crans muraux, longue table en bois de stations interactives et installation de c\xE2ble sismique","Coin d'exposition avec \xE9cran tactile mural, carte sismique de la Suisse et \xE9chantillons de roche sur un comptoir en bois","Jeu tactile \xAB La magnitude d'un s\xE9isme \xBB : un curseur compare le s\xE9isme d'Alaska de 1964 \xE0 la Suisse","Jeu tactile \xAB Localiser un s\xE9isme \xBB : des sismom\xE8tres plac\xE9s sur une carte des Alpes pour trouver l'\xE9picentre","Espace d'exposition avec diorama de paysage \xE9clair\xE9, \xE9cran tactile mural et maquette de maison en bois"],type:"Installation mus\xE9ale",shortDescription:"Parcours d'exposition, mini-jeux tactiles et escape game pour un centre public de formation aux s\xE9ismes",description:"Un centre public de formation aux s\xE9ismes, en Suisse, o\xF9 l'on apprend en jouant ce qu'est un s\xE9isme et comment r\xE9agir. Toute la technologie derri\xE8re : 27 stations interactives sur 3 espaces avec plus de 30 mini-jeux tactiles, con\xE7ues avec des sismologues et des professeurs d'universit\xE9 ; une flotte de 30 tablettes en mode kiosque mises \xE0 jour \xE0 distance ; Escape With Wallis, un escape game d'une heure \xE0 travers l'exposition ; et la plateforme de r\xE9servation et de paiement pour \xE9coles, entreprises et services publics. Le centre abrite aussi le plus grand simulateur de s\xE9isme d'Europe.",features:["Plus de 30 mini-jeux tactiles sur 3 espaces et 27 stations","Flotte de 30 tablettes murales en kiosque, pilot\xE9es et mises \xE0 jour \xE0 distance","Escape With Wallis : escape game d'une heure, plus de 3 000 sessions jou\xE9es","Plateforme de r\xE9servation et de paiement, 50 000 utilisateurs par an","Con\xE7u avec des sismologues et des professeurs d'universit\xE9","Contenus multilingues"]}},{id:"exploreum",category:"Flutter Apps",fit:["app","game","museum","public"],type:"Edutainment App",title:"Exploreum",shortDescription:"Museums, towns and walks turned into interactive stories to play on your phone",description:"Exploreum turns a museum visit, a walk through town or an outdoor site into a story to play on a phone. Each experience mixes illustrated pages with quizzes, estimates, sorting challenges and map games; guided walks always show the next stop, and some experiences unlock on site with a QR code. No account, no ads, in French, English and German. Partner museums and venues run their own scenarios and events from a web back office.",icon:"\u{1F9ED}",thumbnail:"/assets/projects/exploreum/exploreum-en-1-thumb.webp",media:["/assets/projects/exploreum/exploreum-en-1.jpg","/assets/projects/exploreum/exploreum-en-2.jpg","/assets/projects/exploreum/exploreum-en-3.jpg","/assets/projects/exploreum/exploreum-en-4.jpg","/assets/projects/exploreum/exploreum-en-5.jpg"],alt:["Story intro: a night mountain lit by a flash, 'Step inside the story'","Hands-on challenge: draw distance circles on a map to find the vent of an eruption","Trail map of Visp with numbered stops through the old town","Hazard Watch experience card: virtual, about 20 minutes, with a start button","Badges screen with milestones and streaks to collect"],tech:["Flutter","Firebase","Cloud Functions","Next.js","App Check","OpenStreetMap"],features:["Illustrated story pages with quizzes, estimates, sorting and puzzle challenges","On-site experiences unlocked by QR code on printed signs","Guided walks with a step-by-step map","Audio guide and several languages for some experiences","Daily streak, badges, and resume where you left off",'"Near you" list, only when location is shared',"A page for each partner museum and venue","Web back office for partners: scenarios, events, printed codes","Play without an account; iPhone, Android and web"],links:[{label:"Try the App",labelFr:"Essayer l'app",href:"https://exploreum.coldsnap.fr/",icon:"fa-globe"},{label:"Google Play",href:"https://play.google.com/store/apps/details?id=com.coldsnap.exploreum",icon:"fa-android",style:"play-store"},{label:"App Store",href:"https://apps.apple.com/app/exploreum/id6822310253",icon:"fa-apple",style:"app-store"}],fr:{alt:["Introduction de l'histoire : une montagne de nuit \xE9clair\xE9e par un \xE9clair, \xAB Entrez dans l'histoire \xBB","D\xE9fi concret : tracer des cercles de distance sur une carte pour trouver la chemin\xE9e d'une \xE9ruption","Carte du parcours de Vi\xE8ge avec des \xE9tapes num\xE9rot\xE9es dans la vieille ville","Fiche de l'exp\xE9rience Hazard Watch : virtuelle, environ 20 minutes, avec un bouton pour commencer","\xC9cran des badges : \xE9tapes et s\xE9ries \xE0 collectionner"],type:"App ludo-\xE9ducative",shortDescription:"Mus\xE9es, villes et balades deviennent des histoires interactives \xE0 jouer sur son t\xE9l\xE9phone",description:"Exploreum transforme la visite d'un mus\xE9e, une balade en ville ou un site en plein air en une histoire \xE0 jouer sur son t\xE9l\xE9phone. Chaque exp\xE9rience m\xEAle pages illustr\xE9es, quiz, estimations, d\xE9fis de tri et jeux sur carte ; les balades guid\xE9es montrent toujours la prochaine \xE9tape, et certaines exp\xE9riences se d\xE9bloquent sur place avec un QR code. Sans compte, sans publicit\xE9, en fran\xE7ais, anglais et allemand. Les mus\xE9es et lieux partenaires g\xE8rent leurs sc\xE9narios et \xE9v\xE9nements depuis un espace web.",thumbnail:"/assets/projects/exploreum/exploreum-fr-1-thumb.webp",media:["/assets/projects/exploreum/exploreum-fr-1.jpg","/assets/projects/exploreum/exploreum-fr-2.jpg","/assets/projects/exploreum/exploreum-fr-3.jpg","/assets/projects/exploreum/exploreum-fr-4.jpg","/assets/projects/exploreum/exploreum-fr-5.jpg"],features:["Pages illustr\xE9es avec quiz, estimations, d\xE9fis de tri et puzzles","Exp\xE9riences sur place d\xE9bloqu\xE9es par QR code sur des panneaux imprim\xE9s","Balades guid\xE9es avec carte, \xE9tape par \xE9tape","Audioguide et plusieurs langues pour certaines exp\xE9riences","S\xE9rie de jours, badges, et reprise l\xE0 o\xF9 on en \xE9tait","Liste \xAB Pr\xE8s de vous \xBB, seulement si la position est partag\xE9e","Une page pour chaque mus\xE9e et lieu partenaire","Espace web pour les partenaires : sc\xE9narios, \xE9v\xE9nements, codes imprim\xE9s","Jouable sans compte ; iPhone, Android et web"]}},{id:"maya",category:"Flutter Apps",fit:["app","public"],type:"Town App",title:"Maya",shortDescription:"The town hall in every resident's pocket: news, alerts, polls, problem reports and local shops",description:"Maya lets a town hall reach every resident on their phone: news, events, urgent alerts and polls in one app, with only the notifications each person picks. Residents report a problem with a photo and a pin, then follow it until it is fixed. News comes from the town's existing website, staff handle the rest from a web back office, and each town adds only the modules it needs: M\xE9t\xE9o-France and Vigicrues warnings, waste collection reminders, a QR code loyalty game for local shops. Free for residents and shops, no ads, no trackers, data hosted in France. First town: Mouans-Sartoux.",icon:"\u{1F41D}",thumbnail:"/assets/projects/maya/maya-en-1-thumb.webp",media:["/assets/projects/maya/maya-trailer-en.mp4","/assets/projects/maya/maya-en-1.jpg","/assets/projects/maya/maya-en-2.jpg","/assets/projects/maya/maya-en-3.jpg","/assets/projects/maya/maya-en-4.jpg","/assets/projects/maya/maya-en-5.jpg","/assets/projects/maya/maya-en-6.jpg"],alt:["Maya trailer: 'What if your town could talk to you?'","Town news home screen with highlights, town hall shortcuts and open polls","Event page with date, place and full description","Report a problem: pick a category, add a photo and place a pin on the map","Notification settings: choose which alerts and news to receive","The Hive: pollen, level and badges earned at local shops","Map of local shops near you with a shop card"],tech:["Flutter","Firebase","Cloud Functions","Next.js","FCM","Google Maps"],features:["News and events imported from the town's website","Push notifications by topic, picked by each resident","Urgent alerts, with M\xE9t\xE9o-France and Vigicrues warnings relayed automatically","Anonymous polls: one vote per account, results after voting","Problem reports with photo and location, tracked until resolved","Waste collection days with a reminder the night before","Map of local shops; the Hive rewards visits with pollen and badges via QR code","Web back office for town hall staff, scheduled posts","iPhone, Android and web; data hosted in France, GDPR compliant"],links:[{label:"Google Play",href:"https://play.google.com/store/apps/details?id=com.coldsnap.maya",icon:"fa-android",style:"play-store"},{label:"App Store",href:"https://apps.apple.com/fr/app/id6820991824",icon:"fa-apple",style:"app-store",soon:!0},{label:"Try the App",labelFr:"Essayer l'app",href:"https://app.mayaville.fr/",icon:"fa-mobile"},{label:"Visit Website",labelFr:"Site web",href:"https://mayaville.fr/",icon:"fa-globe",secondary:!0}],fr:{alt:["Accueil des actualit\xE9s de la commune avec la une, les raccourcis mairie et les sondages en cours","Page d'un \xE9v\xE9nement avec date, lieu et description compl\xE8te","Signaler un probl\xE8me : choisir une cat\xE9gorie, ajouter une photo et placer un rep\xE8re sur la carte","R\xE9glages des notifications : choisir les alertes et actualit\xE9s re\xE7ues","La Ruche : pollen, niveau et badges gagn\xE9s chez les commer\xE7ants","Carte des commerces de proximit\xE9 avec la fiche d'un commerce"],type:"App communale",shortDescription:"La mairie dans la poche de chaque habitant : actus, alertes, sondages, signalements et commerces",description:"Maya permet \xE0 une mairie de joindre chaque habitant sur son t\xE9l\xE9phone : actualit\xE9s, agenda, alertes urgentes et sondages dans une seule app, avec seulement les notifications que chacun choisit. Les habitants signalent un probl\xE8me avec une photo et un rep\xE8re, puis suivent son traitement. Les actualit\xE9s viennent du site de la commune, les agents g\xE8rent le reste depuis un espace web, et chaque commune n'ajoute que les modules utiles : vigilances M\xE9t\xE9o-France et Vigicrues, rappels de collecte des d\xE9chets, jeu de fid\xE9lit\xE9 par QR code pour les commerces. Gratuit pour les habitants et les commer\xE7ants, sans publicit\xE9 ni traceur, donn\xE9es h\xE9berg\xE9es en France. Premi\xE8re commune : Mouans-Sartoux.",thumbnail:"/assets/projects/maya/maya-fr-1-thumb.webp",media:["/assets/projects/maya/maya-fr-1.jpg","/assets/projects/maya/maya-fr-2.jpg","/assets/projects/maya/maya-fr-3.jpg","/assets/projects/maya/maya-fr-4.jpg","/assets/projects/maya/maya-fr-5.jpg","/assets/projects/maya/maya-fr-6.jpg"],features:["Actualit\xE9s et agenda import\xE9s du site de la commune","Notifications par th\xE8me, choisies par chaque habitant","Alertes urgentes, vigilances M\xE9t\xE9o-France et Vigicrues relay\xE9es automatiquement","Sondages anonymes : un vote par compte, r\xE9sultats apr\xE8s le vote","Signalements avec photo et position, suivis jusqu'\xE0 la r\xE9solution","Jours de collecte des d\xE9chets, avec un rappel la veille","Carte des commerces ; la Ruche r\xE9compense les visites en pollen et badges par QR code","Espace mairie sur le web pour les agents, envois programm\xE9s","iPhone, Android et web ; donn\xE9es h\xE9berg\xE9es en France, conforme au RGPD"]}},{id:"spinlab",category:"Flutter Apps",fit:["app","web","company"],type:"Mobile App",title:"SpinLab",shortDescription:"Platform connecting tennis players with certified coaches for booking lessons",description:"SpinLab lets tennis players find a certified coach nearby and book a lesson in a few taps. Coaches show up on a map with their rate and speciality; players pick a slot and pay in the app, and coaches see every paid booking in one list.",icon:"\u{1F3BE}",thumbnail:"/assets/projects/spinlab/spinlab-1-thumb.webp?v=20261029",media:["/assets/projects/spinlab/spinlab-1.jpeg?v=20261029","/assets/projects/spinlab/spinlab-2.jpeg?v=20261029","/assets/projects/spinlab/spinlab-3.jpeg?v=20261029","/assets/projects/spinlab/spinlab-4.jpeg?v=20261029","/assets/projects/spinlab/spinlab-5.jpeg?v=20261029","/assets/projects/spinlab/spinlab-6.jpeg?v=20261029"],alt:["SpinLab coach list with photos, sports, hourly rates and distance","Map of Paris with coach photos as pins","Coach profile with speciality, rate per hour and biography","Booking screen: available days, a calendar and time slots","Booking confirmation dialog with the total and cancellation terms before payment","Coach view of upcoming paid bookings with dates, times and a revoke button"],tech:["Flutter","Dart","Firebase","Stripe","Google Maps"],features:["Geolocated coach discovery","Real-time booking system","Secure payment via Stripe","Training progress tracking","In-app messaging","Review and rating system"],links:[{label:"Google Play",href:"https://play.google.com/store/apps/details?id=com.coldsnap.spinlab",icon:"fa-android",style:"play-store"},{label:"App Store",href:"https://apps.apple.com/fr/app/spinlab/id6758303721",icon:"fa-apple",style:"app-store"},{label:"Visit Website",labelFr:"Site web",href:"https://spinlab.fr",icon:"fa-globe",secondary:!0}],fr:{alt:["Liste des coachs SpinLab avec photos, sports, tarifs horaires et distance","Carte de Paris avec les photos des coachs en rep\xE8res","Profil d'un coach : sp\xE9cialit\xE9, tarif horaire et biographie","\xC9cran de r\xE9servation : jours disponibles, calendrier et cr\xE9neaux horaires","Fen\xEAtre de confirmation de r\xE9servation avec le total et les conditions d'annulation avant paiement","Vue coach des r\xE9servations pay\xE9es \xE0 venir, avec dates, heures et bouton d'annulation"],type:"App mobile",shortDescription:"Plateforme qui met en relation joueurs de tennis et coachs certifi\xE9s pour r\xE9server des cours",description:"SpinLab permet aux joueurs de tennis de trouver un coach certifi\xE9 pr\xE8s de chez eux et de r\xE9server un cours en quelques gestes. Les coachs apparaissent sur une carte avec leur tarif et leur sp\xE9cialit\xE9 ; le joueur choisit un cr\xE9neau et paie dans l'app, et le coach retrouve toutes ses r\xE9servations pay\xE9es dans une seule liste.",features:["Recherche de coachs g\xE9olocalis\xE9e","R\xE9servation en temps r\xE9el","Paiement s\xE9curis\xE9 via Stripe","Suivi de progression","Messagerie int\xE9gr\xE9e","Avis et notes"]}},{id:"sdana-installation",category:"Interactive Installations",fit:["kiosk","museum","public","school"],type:"Touchscreen Installation",title:"SDANA Natural Hazards Installation",shortDescription:"Large-format educational touchscreen teaching visitors about natural hazards in Valais",description:"Helps visitors of the Valais natural hazards service (SDANA) understand avalanches, floods, storms and rockfall, and know how to react when one happens. On a very large touchscreen at the SDANA offices, each hazard unfolds in illustrated scenes, in several languages: what it is, how it forms, what to do.",thumbnail:"/assets/projects/sdana/sdana-1-thumb.webp",media:["/assets/projects/sdana/sdana-1.png","/assets/projects/sdana/sdana-2.png","/assets/projects/sdana/sdana-3.png"],alt:["Home screen of the Natural Hazards touchscreen: illustrated panels of avalanches, floods, storms and rockfall","Storm definition screen: a short explanation next to a photo of a storm cloud over fields","Storm mechanism screen in German: the maturing phase of a cumulonimbus with a step slider"],tech:["Interactive Installation","Large Touchscreen","Multi-language UX"],features:["Built for a large public touchscreen display","Covers multiple natural hazards and risk scenarios","Explains hazard mechanisms with guided visual content","Behaviour and safety guidance for visitors","Multi-language navigation and content"],links:[],fr:{alt:["\xC9cran d'accueil de la borne Dangers naturels : panneaux illustr\xE9s d'avalanches, crues, orages et chutes de pierres","\xC9cran \xAB Orage, d\xE9finition \xBB : une courte explication \xE0 c\xF4t\xE9 d'une photo de nuage d'orage sur des champs","\xC9cran sur le m\xE9canisme de l'orage en allemand : phase de maturit\xE9 d'un cumulonimbus avec curseur d'\xE9tapes"],type:"Installation tactile",shortDescription:"Grand \xE9cran tactile p\xE9dagogique sur les dangers naturels en Valais",description:"Aide les visiteurs du Service des dangers naturels du Valais (SDANA) \xE0 comprendre avalanches, crues, orages et chutes de pierres, et \xE0 savoir comment r\xE9agir. Sur un tr\xE8s grand \xE9cran tactile dans les locaux du SDANA, chaque danger se d\xE9couvre en sc\xE8nes illustr\xE9es et en plusieurs langues : ce que c'est, comment il se forme, que faire.",features:["Con\xE7ue pour un grand \xE9cran tactile public","Couvre plusieurs dangers naturels et sc\xE9narios de risque","Explique les m\xE9canismes avec des contenus visuels guid\xE9s","Conseils de comportement et de s\xE9curit\xE9","Navigation et contenus multilingues"]}},{id:"winston",category:"Flutter Apps",fit:["web","company"],type:"Web App",title:"Winston",shortDescription:"Company-wide admin butler: accounting, contracts, invoicing and AI-powered LinkedIn management in one dashboard",description:"Winston runs the paperwork of a group of companies from one dashboard, so quotes, invoices, expenses and contracts stop living in separate tools. Every document is generated and exported as PDF, and a built-in content tool turns news articles into LinkedIn posts with GPT-4o-mini and publishes them.",icon:"\u{1F916}",thumbnail:"/assets/projects/winston/winston-1-thumb.webp?v=20261110",media:["/assets/projects/winston/winston-1.png?v=20261110"],alt:["Winston accounting dashboard with CHF, EUR and USD ledgers and status overview"],tech:["Flutter Web","Dart","Firebase","OpenAI GPT-4o-mini","LinkedIn API","Cloud Functions"],features:["Quotes, invoices, and business expense management","Contract creation and tracking","PDF generation and export for all documents","Multi-company management from a single dashboard","AI LinkedIn post generation from articles (GPT-4o-mini)","Direct LinkedIn publishing via OAuth","Firebase Authentication and Firestore backend","Serverless Cloud Functions architecture"],links:[],fr:{alt:["Tableau de bord comptable Winston avec registres en CHF, EUR et USD et vue des statuts"],type:"App web",shortDescription:"Le majordome administratif : comptabilit\xE9, contrats, facturation et LinkedIn assist\xE9 par IA dans un seul tableau de bord",description:"Winston g\xE8re la paperasse d'un groupe de soci\xE9t\xE9s depuis un seul tableau de bord : devis, factures, notes de frais et contrats ne sont plus \xE9parpill\xE9s entre plusieurs outils. Chaque document est g\xE9n\xE9r\xE9 et export\xE9 en PDF, et un outil de contenu int\xE9gr\xE9 transforme des articles d'actualit\xE9 en posts LinkedIn avec GPT-4o-mini, puis les publie.",features:["Gestion des devis, factures et notes de frais","Cr\xE9ation et suivi des contrats","G\xE9n\xE9ration et export PDF de tous les documents","Gestion multi-soci\xE9t\xE9s depuis un seul tableau de bord","G\xE9n\xE9ration de posts LinkedIn par IA (GPT-4o-mini)","Publication LinkedIn directe via OAuth","Backend Firebase Authentication et Firestore","Architecture serverless Cloud Functions"]}},{id:"vidanim",category:"Flutter Apps",fit:["app","web","school"],type:"Mobile/Web App",title:"Vidanim",shortDescription:"Activity library for teachers and animators to document, estimate, and share creative work",description:"Vidanim helps teachers and animators keep track of the activities they create for children. Each entry can include photos, required materials, and the time it took to prepare, making it easier to reuse successful ideas and plan future sessions. The app also supports sharing activities with other Vidanim users so teams can collaborate and build a reusable knowledge base together.",thumbnail:"/assets/projects/Vidanim/vidanim%20(1)-thumb.webp",media:["/assets/projects/Vidanim/vidanim%20(1).jpg","/assets/projects/Vidanim/vidanim%20(2).jpg"],alt:["Vidanim activity list: each card shows a photo, a title and a short description","Activity sheet 'Keep talking and nobody explodes' with duration, materials, description and gallery"],tech:["Flutter","Dart","Android","Web"],features:["Create and archive kids activity ideas","Attach multiple photos to each activity","Track required materials and preparation notes","Record how long an activity took to create","Share activities with other users for collaboration","Build a reusable activity library for future sessions"],links:[{label:"Google Play",href:"https://play.google.com/store/apps/details?id=com.coldsnap.vidanim",icon:"fa-android",style:"play-store"}],fr:{alt:["Liste d'activit\xE9s Vidanim : chaque fiche montre une photo, un titre et une courte description","Fiche d'activit\xE9 \xAB Keep talking and nobody explodes \xBB avec dur\xE9e, mat\xE9riel, description et galerie"],type:"App mobile/web",shortDescription:"Biblioth\xE8que d'activit\xE9s pour enseignants et animateurs : documenter, estimer et partager",description:"Vidanim aide les enseignants et animateurs \xE0 garder une trace des activit\xE9s qu'ils cr\xE9ent pour les enfants. Chaque fiche peut contenir des photos, le mat\xE9riel n\xE9cessaire et le temps de pr\xE9paration, pour r\xE9utiliser facilement les bonnes id\xE9es et pr\xE9parer les prochaines s\xE9ances. Les activit\xE9s se partagent entre utilisateurs pour construire ensemble une base de connaissances.",features:["Cr\xE9er et archiver des id\xE9es d'activit\xE9s","Plusieurs photos par activit\xE9","Mat\xE9riel n\xE9cessaire et notes de pr\xE9paration","Temps de cr\xE9ation de chaque activit\xE9","Partage d'activit\xE9s entre utilisateurs","Une biblioth\xE8que r\xE9utilisable pour les prochaines s\xE9ances"]}},{id:"coldsnap-arcade",category:"Games",fit:["game","web"],type:"Retro Arcade",title:"ColdSnap Arcade",coinSlot:"https://arcade.coldsnap.fr/",shortDescription:"Games written for real retro consoles, playable in the browser, with a shared leaderboard",description:"Real games for old consoles, playable from any browser and competing on one leaderboard. The first one, David contre les zombies, is a survival game written in C for the Sega Master System. It runs on the original console from a flash cartridge, and here from the very same ROM.",icon:"\u{1F579}\uFE0F",thumbnail:"/assets/projects/arcade/arcade-3-thumb.webp",media:["/assets/projects/arcade/arcade-3.png","/assets/projects/arcade/arcade-5.png","/assets/projects/arcade/arcade-4.png"],alt:["David contre les zombies, level 5: the player collects blue gems in the Re-Play festival hall while zombies approach","David contre les zombies on the beach level, chased by a horde of zombies","Game over screen: time, level and number of zombies killed"],tech:["C","Z80","SDCC","EmulatorJS","Cloudflare Workers","Cloudflare D1"],features:["Runs the real ROM in the browser, the same file as on the console","One leaderboard for every game, on every console","Keyboard, controller and touch controls","Master System and Super Nintendo score reading tested, more consoles to come"],fr:{alt:["David contre les zombies, niveau 5 : le joueur ramasse des gemmes bleues dans le hall du festival Re-Play pendant que les zombies approchent","David contre les zombies sur le niveau de la plage, poursuivi par une horde de zombies","\xC9cran de fin de partie : temps, niveau et nombre de zombies tu\xE9s"],type:"Arcade r\xE9tro",shortDescription:"Des jeux \xE9crits pour de vraies consoles r\xE9tro, jouables dans le navigateur, avec un classement commun",description:"De vrais jeux pour anciennes consoles, jouables depuis n'importe quel navigateur, avec un seul classement. Le premier, David contre les zombies, est un jeu de survie \xE9crit en C pour la Sega Master System. Il tourne sur la console d'origine depuis une cartouche flash, et ici depuis exactement la m\xEAme ROM.",features:["Fait tourner la vraie ROM dans le navigateur, le m\xEAme fichier que sur la console","Un seul classement pour tous les jeux, sur toutes les consoles","Commandes au clavier, \xE0 la manette et au tactile","Lecture des scores test\xE9e sur Master System et Super Nintendo, d'autres consoles \xE0 venir"]}},{id:"pygmak",category:"Games",fit:["game"],type:"Mobile Game",title:"Pygmak",shortDescription:"Survivors-style arcade on the water: steer a flagship, blast crate hordes, build a run one card at a time",description:"Pygmak is a survivors-style arcade game on the water where the player only steers: crates rain down in hordes, the flagship's gun aims itself, and every level up deals three cards to pick from (burn, freeze, electrify and dozens more), so each run builds differently. Three weapon classes, bosses every two and a half minutes, a final crate at 15:00, then endless mode. Built on realistic 2D physics so every shot, bounce and splash lands.",icon:"\u{1F3AF}",thumbnail:"/assets/projects/pygmak/pygmak-1-thumb.webp",media:["/assets/projects/pygmak/pygmak-1.jpg","/assets/projects/pygmak/pygmak-2.jpg","/assets/projects/pygmak/pygmak-3.jpg","/assets/projects/pygmak/pygmak-4.jpg","/assets/projects/pygmak/pygmak-5.jpg","/assets/projects/pygmak/pygmak-6.jpg","/assets/projects/pygmak/pygmak-7.jpg","/assets/projects/pygmak/pygmak-8.jpg","/assets/projects/pygmak/pygmak-9.jpg"],alt:["Pygmak gameplay: laser beams from a boat break falling crates above green hills","A parachute bomb drops among crates while the boat fires","Level up: pick one of three upgrade cards","Golden chest reward with three rare upgrade cards","Crates of every size falling toward the boat","'Gun jammed!' warning during a run","Main menu with the laser class, best score and Play button","Class and skins screen: cannon, laser and firework weapons","Damage recap at the end of a run, split by weapon"],tech:["Unity 6","C#","URP","UI Toolkit","Feel","LevelPlay Ads","Android"],features:["Steer the flagship; the gun aims itself","Three weapon classes: cannon, laser, firework","Level-up card hands, chest evolutions and a gunboat convoy","Elites, ranked bosses, a 15-minute arc and endless mode","Corrupted crates: split, explode, mines, parachutes","Day/night cycle, seasons, workshop, skins and damage recap"],links:[{label:"Google Play",href:"https://play.google.com/store/apps/details?id=com.coldsnap.pygmak",icon:"fa-android",style:"play-store"}],fr:{alt:["Partie de Pygmak : des rayons laser tir\xE9s d'un bateau brisent des caisses au-dessus de collines vertes","Une bombe en parachute tombe parmi les caisses pendant que le bateau tire","Mont\xE9e de niveau : choisir une carte d'am\xE9lioration parmi trois","Coffre dor\xE9 avec trois cartes d'am\xE9lioration rares","Des caisses de toutes tailles tombent vers le bateau","Alerte \xAB Gun jammed! \xBB pendant une partie","Menu principal avec la classe laser, le meilleur score et le bouton Jouer","\xC9cran des classes et skins : canon, laser et feu d'artifice","Bilan des d\xE9g\xE2ts en fin de partie, r\xE9parti par arme"],type:"Jeu mobile",shortDescription:"Arcade fa\xE7on survivors sur l'eau : pilotez un navire, pulv\xE9risez des hordes de caisses, construisez votre run carte par carte",description:"Pygmak est un jeu d'arcade fa\xE7on survivors sur l'eau o\xF9 le joueur ne fait que piloter : les caisses pleuvent par hordes, le canon du navire vise tout seul, et chaque niveau gagn\xE9 distribue trois cartes \xE0 choisir (feu, gel, \xE9lectricit\xE9 et des dizaines d'autres), pour que chaque partie se construise autrement. Trois classes d'armes, un boss toutes les deux minutes et demie, une caisse finale \xE0 15:00, puis un mode infini. Construit sur une physique 2D r\xE9aliste, pour que chaque tir, rebond et \xE9claboussure ait du poids.",features:["Pilotez le navire ; le canon vise tout seul","Trois classes d'armes : canon, laser, feu d'artifice","Mains de cartes \xE0 chaque niveau, \xE9volutions par coffres, convoi de canonni\xE8res","\xC9lites, boss class\xE9s, un arc de 15 minutes puis un mode infini","Caisses corrompues : division, explosion, mines, parachutes","Cycle jour/nuit, saisons, atelier, skins et r\xE9cap des d\xE9g\xE2ts"]}},{id:"seba",category:"Games",fit:["game","app"],type:"Card Game",title:"Seba",shortDescription:"Collect over 900 mythical creatures and gods, nearly all shown on historic artworks",description:"Seba is a card game of creatures from every culture's myths: dragons, kappa, firebirds, sea serpents and the gods of old pantheons. Open a free pack, peel five stickers and fill your bestiary. Nearly every card shows a public-domain artwork from Wikimedia Commons, The Met, the Cleveland Museum of Art or the Art Institute of Chicago, credited on the card with the creature's tradition and a short description. Rarity means something: legendary cards are the creatures the whole world knows, rare ones are told in only a few languages. Named after Albertus Seba, the 18th-century Amsterdam apothecary whose book of curiosities put real animals beside dragons and a seven-headed hydra.",icon:"\u{1F409}",thumbnail:"/assets/projects/seba/seba-en-1-thumb.webp",media:["/assets/projects/seba/seba-en-1.jpg","/assets/projects/seba/seba-en-2.jpg","/assets/projects/seba/seba-en-3.jpg","/assets/projects/seba/seba-en-4.jpg"],alt:["Unopened Seba card pack: five creatures in every pack","Creature card Uwan, a Japanese yokai painting with its story","Bestiary page 'Gods of Greece' with the first cards found","Home screen: a free pack is ready every hour, with collection counters"],tech:["Flutter","Firebase","Cloud Functions","FCM","In-app purchases"],features:["A free pack every hour, two kept in store, and a push when they are ready","Over 900 creatures and gods, from Greek and Norse myth to Japanese y\u014Dkai","Historic artworks from museum open-access collections, credited on every card","Twelve regions to complete, from the Celtic isles to the Americas","Friends by code, one-for-one trades and a friends leaderboard","The first player to find a card has their name on every copy","Guest play; packs are never sold"],links:[{label:"Google Play",href:"https://play.google.com/store/apps/details?id=com.coldsnap.seba",icon:"fa-android",style:"play-store"}],fr:{alt:["Paquet de cartes Seba ferm\xE9 : cinq cr\xE9atures par paquet","Carte de la cr\xE9ature Zahhak, une miniature persane ancienne avec son histoire","Page du bestiaire \xAB Moyen-Orient et \xC9gypte \xBB avec les premi\xE8res cartes trouv\xE9es","\xC9cran d'accueil : un paquet gratuit chaque heure, avec les compteurs de collection"],type:"Jeu de cartes",shortDescription:"Collectionne plus de 900 cr\xE9atures et dieux mythiques, presque tous sur de vraies \u0153uvres",description:"Seba est un jeu de cartes des cr\xE9atures de tous les mythes du monde : dragons, kappa, oiseaux de feu, serpents de mer et dieux des panth\xE9ons anciens. Ouvre un paquet gratuit, d\xE9colle cinq autocollants et remplis ton bestiaire. Presque chaque carte montre une \u0153uvre du domaine public venue de Wikimedia Commons, du Met, du Cleveland Museum of Art ou de l'Art Institute of Chicago, cr\xE9dit\xE9e sur la carte avec la tradition de la cr\xE9ature et une courte description. La raret\xE9 a du sens : les l\xE9gendaires sont les cr\xE9atures que le monde entier conna\xEEt, les rares ne sont racont\xE9es que dans quelques langues. Le nom vient d'Albertus Seba, apothicaire d'Amsterdam du XVIIIe si\xE8cle dont le livre de curiosit\xE9s pla\xE7ait de vrais animaux \xE0 c\xF4t\xE9 de dragons et d'une hydre \xE0 sept t\xEAtes.",thumbnail:"/assets/projects/seba/seba-fr-1-thumb.webp",media:["/assets/projects/seba/seba-fr-1.jpg","/assets/projects/seba/seba-fr-2.jpg","/assets/projects/seba/seba-fr-3.jpg","/assets/projects/seba/seba-fr-4.jpg"],features:["Un paquet gratuit chaque heure, deux en r\xE9serve, et une notification quand ils sont pr\xEAts","Plus de 900 cr\xE9atures et dieux, des mythes grecs et nordiques aux y\u014Dkai japonais","Des \u0153uvres historiques des collections en acc\xE8s libre des mus\xE9es, cr\xE9dit\xE9es sur chaque carte","Douze r\xE9gions \xE0 compl\xE9ter, des \xEEles celtes aux Am\xE9riques","Amis par code, \xE9changes une carte contre une et classement entre amis","Le premier joueur \xE0 trouver une carte a son nom sur chaque exemplaire","Jeu en invit\xE9 ; les paquets ne sont jamais vendus"]}},{id:"badalone",category:"Games",fit:["game","app"],type:"Card Game",title:"Badalone",shortDescription:"Open packs of real, ridiculous patents drawn from 12 million inventions",description:"Every Badalone pack is nine real patents pulled at random from the entire US patent archive: more than twelve million inventions, from 1836 to last week. A method of swinging on a swing. A hat with a built-in umbrella. The light bulb. Each card shows the original drawing redrawn as a white-on-black blueprint, an absurdity index and the plain-words abstract on the back, and opens the original document in one tap. Rarity is earned by influence: the more later inventions built on a patent, the rarer its card. Named after Il Badalone, Brunelleschi's river barge and the subject of the first patent ever granted (Florence, 1421). No ads, no purchases.",icon:"\u{1F4DC}",thumbnail:"/assets/projects/badalone/badalone-en-1-thumb.webp",media:["/assets/projects/badalone/badalone-en-1.jpg","/assets/projects/badalone/badalone-en-2.jpg","/assets/projects/badalone/badalone-en-3.jpg","/assets/projects/badalone/badalone-en-4.jpg"],alt:["Patent card 'Coherent LADAR using intra-pixel quadrature detection' with its original drawing","Unopened Badalone pack of nine patents, pull the strip to open","Nine new patent cards revealed from one pack","Codex of collected patents with search and filters"],tech:["Flutter","Firebase","Cloud Functions","Patent data","FCM"],features:["Nine random patents per pack, drawn live from 12 million+ inventions","Original drawings redrawn as white-on-black blueprints","Rarity earned by influence, age and collector numbers","An absurdity index and a plain-words abstract for every invention","Searchable codex of every patent discovered","The first player to find a patent has their name on every copy","Friends by code, leaderboard and one-for-one trades; no ads, no purchases"],links:[{label:"Google Play",href:"https://play.google.com/store/apps/details?id=com.coldsnap.badalone",icon:"fa-android",style:"play-store"}],fr:{alt:["Carte brevet \xAB Coherent LADAR using intra-pixel quadrature detection \xBB avec son dessin d'origine","Paquet Badalone de neuf brevets, tirer la bande pour l'ouvrir","Neuf nouvelles cartes brevets r\xE9v\xE9l\xE9es dans un paquet","Codex des brevets collect\xE9s avec recherche et filtres"],type:"Jeu de cartes",shortDescription:"Ouvre des paquets de vrais brevets, souvent absurdes, tir\xE9s de 12 millions d'inventions",description:"Chaque paquet de Badalone contient neuf vrais brevets tir\xE9s au hasard de toutes les archives am\xE9ricaines : plus de douze millions d'inventions, de 1836 \xE0 la semaine derni\xE8re. Une m\xE9thode pour se balancer sur une balan\xE7oire. Un chapeau avec parapluie int\xE9gr\xE9. L'ampoule \xE9lectrique. Chaque carte montre le dessin d'origine redessin\xE9 en plan blanc sur noir, un indice d'absurdit\xE9 et le r\xE9sum\xE9 en mots simples au dos, et ouvre le document original en un geste. La raret\xE9 se gagne par l'influence : plus d'inventions se sont appuy\xE9es sur un brevet, plus sa carte est rare. Le nom vient d'Il Badalone, la barge fluviale de Brunelleschi, objet du tout premier brevet (Florence, 1421). Sans publicit\xE9, sans achat.",features:["Neuf brevets au hasard par paquet, tir\xE9s en direct de plus de 12 millions d'inventions","Les dessins d'origine redessin\xE9s en plans blanc sur noir","Une raret\xE9 gagn\xE9e par l'influence, l'\xE2ge et le num\xE9ro de collection","Un indice d'absurdit\xE9 et un r\xE9sum\xE9 en mots simples pour chaque invention","Un codex de tous les brevets d\xE9couverts, avec recherche","Le premier joueur \xE0 trouver un brevet a son nom sur chaque exemplaire","Amis par code, classement et \xE9changes une contre une ; sans pub ni achat"]}},{id:"helpdetective",hidden:!0,category:"Interactive Installations",fit:["game","school","public","company"],type:"VR Training",title:"Petites Attentions",shortDescription:"Standalone VR on Meta Quest: step into a care job through 360\xB0 video, answer questions and spot the dangers",description:"Makes people want to work in care jobs that are little known or undervalued, such as childcare, by letting them live a moment of the job in VR. In a 360\xB0 scene filmed in a real home, the player answers questions about what is happening and hunts for hidden dangers with a flashlight. Runs offline on Meta Quest 2 and 3, and trainers write new scenarios inside the headset, with no new build.",icon:"\u{1F97D}",thumbnail:"/assets/projects/helpdetective/petites-attentions-1-thumb.webp",media:["/assets/projects/helpdetective/petites-attentions-1.jpg","/assets/projects/helpdetective/petites-attentions-2.jpg","/assets/projects/helpdetective/petites-attentions-3.jpg","/assets/projects/helpdetective/petites-attentions-4.jpg"],alt:["A frosted question card floating over a 360\xB0 video of a living room: what is the adult doing while the child talks?","The right answer turns green and an explanation appears, with a Continue button","End screen: 2/2 right first time, 2 of 3 dangers spotted, the dangers found and what to do next","Petites Attentions menu on a pastel sky with drifting lights, the 'Le salon' scenario card and the workshop button"],tech:["Unity 6","OpenXR","Meta Quest","UI Toolkit","360\xB0 video"],features:["360\xB0 video that pauses for multiple-choice questions","Flashlight hunt for hidden dangers in each scene","Smooth scrubbing through time with the thumbstick","In-headset workshop to create and edit scenarios","Fully offline on Quest 2 and Quest 3","Explanations after a wrong answer, then a retry"],links:[],fr:{alt:["Une carte de question givr\xE9e flotte devant une vid\xE9o 360\xB0 d'un salon : que fait l'adulte pendant que l'enfant lui parle ?","La bonne r\xE9ponse passe au vert et une explication s'affiche, avec un bouton Continuer","\xC9cran de fin : 2/2 bonnes r\xE9ponses du premier coup, 2 dangers rep\xE9r\xE9s sur 3, la liste des dangers trouv\xE9s et la suite","Menu de Petites Attentions sur un ciel pastel avec des lumi\xE8res qui d\xE9rivent, la carte du sc\xE9nario \xAB Le salon \xBB et le bouton Atelier"],type:"Formation en VR",shortDescription:"VR autonome sur Meta Quest : se glisser dans un m\xE9tier du soin en vid\xE9o 360\xB0, r\xE9pondre aux questions et rep\xE9rer les dangers",description:"Donner envie de travailler dans des m\xE9tiers du soin m\xE9connus ou peu valoris\xE9s, comme la petite enfance, en en faisant vivre un moment en VR. Dans une sc\xE8ne 360\xB0 film\xE9e dans un vrai logement, le joueur r\xE9pond \xE0 des questions sur ce qui se passe et cherche les dangers cach\xE9s \xE0 la lampe torche. Fonctionne hors ligne sur Meta Quest 2 et 3, et les formateurs \xE9crivent de nouveaux sc\xE9narios directement dans le casque, sans nouvelle version de l'app.",features:["Vid\xE9o 360\xB0 qui s'arr\xEAte pour des questions \xE0 choix multiples","Chasse aux dangers cach\xE9s \xE0 la lampe torche","Avance et retour fluides dans le temps au stick","Atelier dans le casque pour cr\xE9er et modifier les sc\xE9narios","Enti\xE8rement hors ligne sur Quest 2 et Quest 3","Explication apr\xE8s une mauvaise r\xE9ponse, puis nouvel essai"]}},{id:"propos",category:"Flutter Apps",fit:["app","web","company"],type:"Film & TV Tool",title:"PropOS",shortDescription:"Fake phone screens for film and TV sets, triggered live from a control room and mirrored in real time",description:"PropOS makes the phones and screens actors hold on set do exactly what the scene needs, on cue, take after take. A prop device joins with a short code and shows a believable phone: lock screen with a scripted clock, incoming calls, live texts with typing, hacker terminals. The crew fires each beat from a web control room and sees every device mirrored live, exactly as the camera does. In development.",icon:"\u{1F3AC}",thumbnail:"/assets/projects/propos/propos-1-thumb.webp",media:["/assets/projects/propos/propos-1.jpg","/assets/projects/propos/propos-2.jpg","/assets/projects/propos/propos-3.jpg"],alt:["Prop phone showing an incoming call from 'Mom' with Decline and Accept buttons","Prop messaging screen: a text from Alex, 'Don't come home. They're watching the house.'","Prop lock screen with a scripted clock at 21:47 and a fake carrier name"],tech:["Flutter","Next.js","Firebase Realtime Database","Firestore","Android","iOS","Web"],features:["Phone shell, calls, messaging and terminal templates","Devices pair with a 6-character code, no accounts","GO cue list, blackout and remote brightness","Truthful live mirror of every prop device","Scripted status bar: clock, battery, carrier","Event log of every cue and actor tap"],links:[],fr:{alt:["T\xE9l\xE9phone accessoire affichant un appel entrant de \xAB Mom \xBB avec les boutons Refuser et Accepter","\xC9cran de messagerie accessoire : un SMS d'Alex, \xAB Don't come home. They're watching the house. \xBB","\xC9cran verrouill\xE9 accessoire avec une heure sc\xE9naris\xE9e \xE0 21:47 et un faux op\xE9rateur"],type:"Outil cin\xE9ma et TV",shortDescription:"Faux \xE9crans de t\xE9l\xE9phone pour les tournages, d\xE9clench\xE9s en direct depuis une r\xE9gie et affich\xE9s en miroir",description:"PropOS fait faire aux t\xE9l\xE9phones et \xE9crans tenus par les com\xE9diens exactement ce que la sc\xE8ne demande, au bon moment, prise apr\xE8s prise. Un appareil rejoint la session avec un code court et affiche un t\xE9l\xE9phone cr\xE9dible : \xE9cran verrouill\xE9 \xE0 l'heure sc\xE9naris\xE9e, appels entrants, SMS en direct avec saisie, terminaux de hacker. L'\xE9quipe d\xE9clenche chaque moment depuis une r\xE9gie web et voit chaque appareil en miroir, exactement comme la cam\xE9ra. En d\xE9veloppement.",features:["Mod\xE8les t\xE9l\xE9phone, appel, messagerie et terminal","Appairage par code \xE0 6 caract\xE8res, sans compte","Liste de cues avec bouton GO, noir et luminosit\xE9 \xE0 distance","Miroir fid\xE8le et en direct de chaque appareil","Barre d'\xE9tat sc\xE9naris\xE9e : heure, batterie, op\xE9rateur","Journal de chaque cue et de chaque geste du com\xE9dien"]}},{id:"sandlog",category:"Flutter Apps",fit:["app"],type:"Mobile App",title:"Sandlog",shortDescription:"Voice dream journal: open the app, speak, and your dream is saved automatically",description:"A frictionless dream journaling app designed to capture dreams the moment you wake up. Open the app and speak; Sandlog automatically stops recording when silence is detected and saves your dream entry. Recordings can be exported to the user's Google Drive for safe cloud storage.",icon:"\u{1F319}",thumbnail:"/assets/projects/sandlog/sandlog-1-thumb.webp?v=20261030",media:["/assets/projects/sandlog/sandlog-1.jpg?v=20261030","/assets/projects/sandlog/sandlog-2.jpg?v=20261030","/assets/projects/sandlog/sandlog-3.jpg?v=20261030","/assets/projects/sandlog/sandlog-4.jpg?v=20261030"],alt:["Sandlog capture screen: a microphone button to record a dream by voice","Recording in progress with spoken words floating around the stop button","Dream journal listing dated dreams with titles and summaries","Settings: language, stop after silence, auto-start and Google Drive backup"],tech:["Flutter","Dart","Google Drive API","Voice Recording","Silence Detection"],features:["Instant recording on app open, no buttons needed","Automatic stop on silence detection","Voice dream entry storage","Google Drive export for cloud backup"],links:[{label:"Google Play",href:"https://play.google.com/store/apps/details?id=com.coldsnap.sandlog",icon:"fa-android",style:"play-store"}],fr:{alt:["\xC9cran de capture Sandlog : un bouton micro pour enregistrer un r\xEAve \xE0 la voix","Enregistrement en cours, les mots prononc\xE9s flottent autour du bouton stop","Journal des r\xEAves : r\xEAves dat\xE9s avec titres et r\xE9sum\xE9s","R\xE9glages : langue, arr\xEAt apr\xE8s silence, d\xE9marrage auto et sauvegarde Google Drive"],type:"App mobile",shortDescription:"Journal de r\xEAves vocal : ouvrez l'app, parlez, votre r\xEAve est enregistr\xE9",description:"Un journal de r\xEAves sans friction, pens\xE9 pour capturer un r\xEAve d\xE8s le r\xE9veil. Ouvrez l'app et parlez : Sandlog s'arr\xEAte automatiquement quand le silence revient et enregistre votre r\xEAve. Les enregistrements peuvent \xEAtre export\xE9s vers Google Drive.",features:["Enregistrement d\xE8s l'ouverture, sans bouton","Arr\xEAt automatique au silence","Stockage des r\xEAves en audio","Export Google Drive pour la sauvegarde"]}},{id:"badger",category:"Flutter Apps",fit:["app","company"],type:"Mobile App",title:"Badger",shortDescription:"NFC-powered digital business card, share contacts by tapping phones",description:"A modern replacement for physical business cards. Badger lets you share your contact details instantly by tapping phones via NFC, or via QR code as a fallback. Create beautiful digital card profiles, export as VCF, and manage all your shared contacts in one place.",icon:"\u{1FAAA}",thumbnail:"/assets/projects/badger/badger-1-thumb.webp",media:["/assets/projects/badger/badger-1.jpg","/assets/projects/badger/badger-2.jpg?v=20261110","/assets/projects/badger/badger-3.jpg"],alt:["Badger profile screen with contact card settings and cloud sync","Digital business card ready to share, with phone, email and website","Share screen: show or scan a QR code, NFC and contact file"],tech:["Flutter","Dart","NFC","Firebase","QR Code","Material Design 3"],features:["NFC contact sharing (NDEF format)","QR code fallback for non-NFC devices","Beautiful digital card templates","VCF export and sharing","Firebase profile cloud storage","Material Design 3 UI"],links:[{label:"Google Play",href:"https://play.google.com/store/apps/details?id=com.coldsnap.badger",icon:"fa-android",style:"play-store"}],fr:{alt:["\xC9cran profil de Badger avec r\xE9glages de la carte de contact et synchronisation","Carte de visite num\xE9rique pr\xEAte \xE0 partager, avec t\xE9l\xE9phone, e-mail et site web","\xC9cran de partage : afficher ou scanner un QR code, NFC et fichier contact"],type:"App mobile",shortDescription:"Carte de visite num\xE9rique NFC : partagez vos coordonn\xE9es en rapprochant deux t\xE9l\xE9phones",description:"Le rempla\xE7ant moderne de la carte de visite papier. Badger partage vos coordonn\xE9es instantan\xE9ment en rapprochant deux t\xE9l\xE9phones (NFC), ou par QR code en secours. Cr\xE9ez de belles cartes num\xE9riques, exportez-les en VCF et retrouvez tous vos contacts au m\xEAme endroit.",features:["Partage de contact NFC (format NDEF)","QR code pour les appareils sans NFC","Mod\xE8les de cartes soign\xE9s","Export et partage VCF","Profils stock\xE9s sur Firebase","Interface Material Design 3"]}},{id:"colismarket",category:"Flutter Apps",fit:["app","company"],type:"Mobile App",title:"ColisMarket",shortDescription:"Parcel relay point management app with OCR scanning for package tracking",description:"ColisMarket speeds up parcel intake at relay points: the operator photographs the label and the app reads the parcel details by itself (ML Kit OCR), then records the handover with the customer's signature.",icon:"\u{1F4E6}",thumbnail:"/assets/projects/colismarket/colismarket-1-thumb.webp",media:["/assets/projects/colismarket/colismarket-1.jpg","/assets/projects/colismarket/colismarket-2.jpg","/assets/projects/colismarket/colismarket-3.jpg","/assets/projects/colismarket/colismarket-4.jpg"],alt:["ColisMarket home: choose customer or courier, with today's counters","Scanning a parcel label, analysis in progress","Parcel pickup form pre-filled by OCR: tracking number, sender, recipient and weight","Customer signature pad to confirm the parcel handover"],tech:["Flutter","Dart","Google ML Kit","OCR","Android"],features:["ML Kit OCR for parcel label scanning","Package intake and tracking management","Image capture and document scanning","Relay point operator dashboard","Local persistent storage"],links:[],fr:{alt:["Accueil ColisMarket : choisir client ou livreur, avec les compteurs du jour","Scan de l'\xE9tiquette d'un colis, analyse en cours","Formulaire de retrait pr\xE9-rempli par OCR : num\xE9ro de suivi, exp\xE9diteur, destinataire et poids","Zone de signature du client pour confirmer la remise du colis"],type:"App mobile",shortDescription:"Gestion de points relais avec lecture OCR des \xE9tiquettes pour le suivi des colis",description:"ColisMarket acc\xE9l\xE8re la prise en charge des colis en point relais : l'op\xE9rateur photographie l'\xE9tiquette, l'app en lit les informations toute seule (OCR ML Kit), puis enregistre la remise avec la signature du client.",features:["Lecture OCR des \xE9tiquettes avec ML Kit","Prise en charge et suivi des colis","Capture d'images et num\xE9risation de documents","Tableau de bord op\xE9rateur de point relais","Stockage local persistant"]}},{id:"patoune",category:"Flutter Apps",fit:["app"],type:"Mobile App",title:"Patoune",shortDescription:"Cat claw trimming tracker to visualize and schedule your cat's nail maintenance",description:"A charming companion app for cat owners that makes claw maintenance easy and stress-free. Patoune provides a visual paw diagram to track which claws have been trimmed, colour-coded reminders when trimming is due, and guidance on safe trimming techniques.",icon:"\u{1F43E}",thumbnail:"/assets/projects/patoune/patoune-1-thumb.webp",media:["/assets/projects/patoune/patoune-1.jpg","/assets/projects/patoune/patoune-2.jpg"],alt:["Patoune: a cat drawing with buttons on each claw to mark which ones were trimmed","Claw care guide with four tips and a diagram of where to cut"],tech:["Flutter","Dart","SharedPreferences","SVG","i18n"],features:["Visual paw diagram for per-claw tracking","Colour-coded trimming reminders","Safe trimming technique guidance","Multi-language support","Custom SVG paw assets","Android and Windows support"],links:[{label:"Google Play",href:"https://play.google.com/store/apps/details?id=com.patoune.app.patoune",icon:"fa-android",style:"play-store"}],fr:{alt:["Patoune : un dessin de chat avec un bouton sur chaque griffe pour noter celles coup\xE9es","Guide de soin des griffes : quatre conseils et un sch\xE9ma de l'endroit o\xF9 couper"],type:"App mobile",shortDescription:"Suivi de la coupe des griffes de votre chat, griffe par griffe",description:"Une app attachante pour les propri\xE9taires de chats qui rend l'entretien des griffes simple et sans stress. Patoune propose un sch\xE9ma de patte pour suivre chaque griffe coup\xE9e, des rappels color\xE9s quand il est temps, et des conseils pour couper en toute s\xE9curit\xE9.",features:["Sch\xE9ma de patte, suivi griffe par griffe","Rappels color\xE9s","Conseils de coupe en s\xE9curit\xE9","Multilingue","Illustrations SVG sur mesure","Android et Windows"]}},{id:"posti",category:"Flutter Apps",fit:["app"],type:"Desktop App",title:"Posti",shortDescription:"Minimalist always-on-top system tray todo and notes app for desktop",description:"A lightweight desktop productivity app that lives in your system tray. Posti stays always-on-top for instant access to todos and quick notes without switching context. Designed for minimal friction, capture a thought in seconds and get back to work.",icon:"\u{1F4CC}",thumbnail:"/assets/projects/posti/posti-1-thumb.webp",media:["/assets/projects/posti/posti-1.png"],alt:["Posti to-do window with two open tasks and an archived list"],tech:["Flutter","Dart","Windows","macOS"],features:["System tray integration","Always-on-top window","Quick todo and note capture","Persistent background process","Minimal, distraction-free UI"],links:[{label:"GitHub",href:"https://github.com/Yukisando/Posti",icon:"fa-github"}],fr:{alt:["Fen\xEAtre de t\xE2ches Posti avec deux t\xE2ches en cours et une liste archiv\xE9e"],type:"App de bureau",shortDescription:"Todo et notes minimalistes, toujours au premier plan, dans la barre syst\xE8me",description:"Une petite app de productivit\xE9 qui vit dans la barre syst\xE8me. Posti reste au premier plan pour acc\xE9der instantan\xE9ment \xE0 vos t\xE2ches et notes sans changer de contexte. Z\xE9ro friction : notez une id\xE9e en quelques secondes et reprenez le travail.",features:["Int\xE9gration \xE0 la barre syst\xE8me","Fen\xEAtre toujours au premier plan","Saisie rapide de t\xE2ches et de notes","Processus persistant en arri\xE8re-plan","Interface minimaliste, sans distraction"]}},{id:"grapple-groove",category:"Games",fit:["game"],type:"PC Game",title:"GrappleGroove",shortDescription:"First-person grappling hook game in a giant playroom, with a campaign, a level editor and community levels",description:"A first-person platformer built around two grappling hooks and momentum: swing, reel in and let go at the right moment to fly across a giant toy-filled playroom. The campaign walks through hand-designed levels that each teach one idea. The same level editor used to build them ships in the game: place pieces, test from the camera, set a par time by playing, then publish the level for everyone. Speedrun leaderboards race your best ghost, co-op sessions join by code, and the music is generated live from a toybox of mallets and bells. Built for Steam, with a browser version to try now.",icon:"\u{1FA9D}",thumbnail:"/assets/projects/grapple-groove/grapple-groove-1-thumb.webp?v=20261110",media:["/assets/projects/grapple-groove/grapple-groove-3.jpg","/assets/projects/grapple-groove/grapple-groove-4.jpg"],alt:["First-person view in a giant playroom: blue and red gloves, a pool and a yellow platform ahead, bookshelves and bunting behind","The in-game level editor: Move, Scale and Rotate tools, Test buttons and a green track over water with grapple lines"],tech:["Unity 6","C#","URP","UI Toolkit","Netcode for GameObjects","Firebase","WebGL"],features:["Two grappling hooks driven by momentum physics","Campaign of hand-designed levels","In-game level editor with instant test runs","Publish and play community levels","Speedrun leaderboards with your best ghost","Online co-op sessions joined by code","Procedural toybox music"],links:[{label:"Play in the browser",labelFr:"Jouer dans le navigateur",href:"https://gg.coldsnap.fr/",icon:"fa-play"}],fr:{alt:["Vue subjective dans une salle de jeux g\xE9ante : gants bleu et rouge, une piscine et une plateforme jaune devant, \xE9tag\xE8res et guirlandes derri\xE8re","L'\xE9diteur de niveaux du jeu : outils D\xE9placer, \xC9chelle et Rotation, boutons de test et une piste verte au-dessus de l'eau avec des lignes de grappin"],type:"Jeu PC",shortDescription:"Jeu de grappin \xE0 la premi\xE8re personne dans une salle de jeux g\xE9ante, avec campagne, \xE9diteur de niveaux et niveaux de la communaut\xE9",description:"Un jeu de plateforme \xE0 la premi\xE8re personne construit autour de deux grappins et de l'\xE9lan : se balancer, enrouler, l\xE2cher au bon moment pour traverser une salle de jeux g\xE9ante remplie de jouets. La campagne encha\xEEne des niveaux con\xE7us \xE0 la main, chacun autour d'une id\xE9e. L'\xE9diteur qui a servi \xE0 les construire est dans le jeu : poser des pi\xE8ces, tester depuis la cam\xE9ra, fixer un temps de r\xE9f\xE9rence en jouant, puis publier le niveau pour tout le monde. Classements de speedrun contre son meilleur fant\xF4me, parties en coop\xE9ration rejointes par code, et une musique g\xE9n\xE9r\xE9e en direct \xE0 partir d'une bo\xEEte \xE0 jouets de marimbas et de clochettes. Pens\xE9 pour Steam, avec une version navigateur \xE0 essayer d\xE8s maintenant.",features:["Deux grappins et une physique d'\xE9lan","Campagne de niveaux con\xE7us \xE0 la main","\xC9diteur de niveaux int\xE9gr\xE9 avec test imm\xE9diat","Publier et jouer les niveaux de la communaut\xE9","Classements de speedrun avec son meilleur fant\xF4me","Coop\xE9ration en ligne rejointe par code","Musique g\xE9n\xE9r\xE9e fa\xE7on bo\xEEte \xE0 jouets"]}},{id:"sharekm",category:"Open Source",type:"Windows App",title:"ShareKM",shortDescription:"Share one keyboard and mouse between two Windows PCs, with encrypted pairing and shared clipboard",description:"A tiny Windows tray app that lets one keyboard and mouse control two PCs on the same network, with clipboard text shared both ways. One hotkey switches which PC you are on. It finds the other PC by itself, pairs with a passphrase and encrypts everything it sends (AES-256-GCM), and can optionally run as administrator to control elevated windows. A single self-contained exe: no install, no account, no PowerToys. Free for non-commercial use, with the source on GitHub.",icon:"\u2328\uFE0F",thumbnail:"/assets/projects/sharekm/sharekm-1-thumb.webp",media:["/assets/projects/sharekm/sharekm-1.png","/assets/projects/sharekm/sharekm-2.png","/assets/projects/sharekm/sharekm-3.png"],alt:["ShareKM in dark mode: connected to a laptop, encryption, hotkey and performance settings","ShareKM in light mode with the same connection and security settings","Warning dialog before running ShareKM as administrator"],tech:["C#",".NET","WinForms","Win32 hooks","AES-GCM"],features:["One hotkey to switch control between your PCs (rebindable with a Record button)","Finds other PCs running ShareKM on the network automatically","Passphrase pairing with AES-256-GCM encryption on the link","Clipboard text shared in both directions","Adjustable mouse update rate (60-1000 Hz)","Optional administrator mode to control elevated windows","Windows 11 style settings window, follows light and dark mode","Single self-contained exe, starts with Windows"],links:[{label:"Download",labelFr:"T\xE9l\xE9charger",href:"https://github.com/Yukisando/ShareKM/releases/latest",icon:"fa-download"},{label:"GitHub",href:"https://github.com/Yukisando/ShareKM",icon:"fa-github",secondary:!0}],fr:{alt:["ShareKM en mode sombre : connect\xE9 \xE0 un portable, chiffrement, raccourci et r\xE9glages de performance","ShareKM en mode clair avec les m\xEAmes r\xE9glages de connexion et de s\xE9curit\xE9","Avertissement avant de lancer ShareKM en administrateur"],type:"App Windows",shortDescription:"Partagez un clavier et une souris entre deux PC Windows, avec appairage chiffr\xE9 et presse-papiers partag\xE9",description:"Une petite app Windows dans la barre syst\xE8me qui permet de piloter deux PC du m\xEAme r\xE9seau avec un seul clavier et une seule souris, avec le texte du presse-papiers partag\xE9 dans les deux sens. Un raccourci clavier suffit pour passer d'un PC \xE0 l'autre. Elle trouve l'autre PC toute seule, s'appaire avec une phrase secr\xE8te et chiffre tout ce qu'elle envoie (AES-256-GCM), et peut tourner en administrateur pour piloter les fen\xEAtres \xE9lev\xE9es. Un seul ex\xE9cutable autonome : sans installation, sans compte, sans PowerToys. Gratuit pour un usage non commercial, code source sur GitHub.",features:["Un raccourci pour passer d'un PC \xE0 l'autre (modifiable avec un bouton Enregistrer)","D\xE9tecte automatiquement les autres PC qui font tourner ShareKM sur le r\xE9seau","Appairage par phrase secr\xE8te et chiffrement AES-256-GCM du lien","Texte du presse-papiers partag\xE9 dans les deux sens","Fr\xE9quence de mise \xE0 jour de la souris r\xE9glable (60 \xE0 1000 Hz)","Mode administrateur facultatif pour piloter les fen\xEAtres \xE9lev\xE9es","Fen\xEAtre de r\xE9glages style Windows 11, th\xE8me clair et sombre","Un seul ex\xE9cutable autonome, d\xE9marrage avec Windows"]}},{id:"waddonsync",category:"Open Source",type:"Desktop App",title:"WaddonSync",shortDescription:"Backup World of Warcraft addon data to Google Drive automatically",description:"A desktop utility that securely backs up your World of Warcraft addon data to Google Drive. Never lose your addon settings, keybindings, or UI configurations again.",icon:"\u{1F3AE}",thumbnail:"/assets/projects/waddonsync/waddonsync-1-thumb.webp",media:["/assets/projects/waddonsync/waddonsync-1.png","/assets/projects/waddonsync/waddonsync-2.png","/assets/projects/waddonsync/waddonsync-3.png"],alt:["WaddonSync backup created, with an offer to upload it to Google Drive","Manage backups: local and Google Drive copies of World of Warcraft settings","Backup options for World of Warcraft folders while a backup is being created"],tech:["Flutter","Dart","Google Drive API","OAuth 2.0"],features:["Backup and restore of WoW addon data","Secure Google Drive integration","Multiple WoW installation support","Easy selection of interface options"],links:[{label:"Download",labelFr:"T\xE9l\xE9charger",href:"https://github.com/Yukisando/WaddonSync/releases",icon:"fa-download"},{label:"GitHub",href:"https://github.com/Yukisando/WaddonSync",icon:"fa-github",secondary:!0}],fr:{alt:["Sauvegarde WaddonSync cr\xE9\xE9e, avec la proposition de l'envoyer sur Google Drive","Gestion des sauvegardes : copies locales et Google Drive des r\xE9glages World of Warcraft","Options de sauvegarde des dossiers World of Warcraft pendant la cr\xE9ation d'une sauvegarde"],type:"App de bureau",shortDescription:"Sauvegarde automatique des donn\xE9es d'addons World of Warcraft sur Google Drive",description:"Un utilitaire de bureau qui sauvegarde en toute s\xE9curit\xE9 les donn\xE9es de vos addons World of Warcraft sur Google Drive. Ne perdez plus jamais vos r\xE9glages, raccourcis ou interfaces.",features:["Sauvegarde et restauration des donn\xE9es d'addons","Int\xE9gration Google Drive s\xE9curis\xE9e","Plusieurs installations de WoW","S\xE9lection simple des options d'interface"]}},{id:"magic-arrow",category:"Open Source",type:"Minecraft Plugin",title:"Magic Arrow",shortDescription:"Minecraft plugin adding block-placing and elemental abilities to bows based on the block you stand on",description:"A Java Minecraft plugin built from scratch that gives the bow and arrow context-sensitive superpowers. The effect fired depends on the block under the player's feet: standing on ice fires a freeze arrow, on TNT fires an explosive, on grass places blocks, and so on. A fun exploration of the Bukkit/Spigot API.",icon:"\u{1F3F9}",thumbnail:"/assets/projects/magic-arrow/magic-arrow-1-thumb.webp",media:["/assets/projects/magic-arrow/magic-arrow-1.jpg"],alt:["Magic Arrow in Minecraft: first-person view drawing a bow at night in a blocky forest"],tech:["Java","Bukkit/Spigot API","Minecraft"],features:["Context-sensitive bow abilities based on standing block","Block-placing arrows","Elemental effects (freeze, explode, and more)","Built from scratch on the Bukkit/Spigot API"],links:[{label:"GitHub",href:"https://github.com/Yukisando/MagicArrow",icon:"fa-github"}],fr:{alt:["Magic Arrow dans Minecraft : vue subjective, arc band\xE9 de nuit dans une for\xEAt en blocs"],type:"Plugin Minecraft",shortDescription:"Plugin Minecraft qui donne \xE0 l'arc des pouvoirs selon le bloc sous vos pieds",description:"Un plugin Minecraft en Java, \xE9crit de z\xE9ro, qui donne \xE0 l'arc des super-pouvoirs contextuels. L'effet d\xE9pend du bloc sous les pieds du joueur : sur la glace une fl\xE8che gelante, sur la TNT une fl\xE8che explosive, sur l'herbe une fl\xE8che qui pose des blocs, etc. Une exploration ludique de l'API Bukkit/Spigot.",features:["Pouvoirs de l'arc selon le bloc sous le joueur","Fl\xE8ches qui posent des blocs","Effets \xE9l\xE9mentaires (gel, explosion, et plus)","\xC9crit de z\xE9ro sur l'API Bukkit/Spigot"]}},{id:"bolt",category:"Open Source",type:"WoW Addon",title:"B.O.L.T",shortDescription:"Modular World of Warcraft addon that restyles Blizzard's own UI and adds small quality-of-life tweaks, for Midnight and WoW: Forever",description:"B.O.L.T (Brittle and Occasionally Lethal Tweaks) makes the World of Warcraft interface cleaner without replacing it: small modules restyle Blizzard's own frames with Blizzard's own art. Portrait-less unit frames, a square minimap with one button bar, bars that fade until needed, nameplates that flag mana users and interruptible casts. Each module is switched on on its own and set from Edit Mode, on Midnight and on WoW: Forever.",icon:"\u2694\uFE0F",thumbnail:"/assets/projects/bolt/bolt-1-thumb.webp",media:["/assets/projects/bolt/bolt-1.png","/assets/projects/bolt/bolt-2.png"],alt:["B.O.L.T options panel inside World of Warcraft with its modules and settings","Redesigned World of Warcraft game menu with expansion shortcuts added by B.O.L.T"],tech:["Lua","World of Warcraft API","GitHub Actions","CI/CD"],features:["Game Menu enhancements (Leave Group, Reload UI, Group Tools)","Portrait-less unit frames and cast bars in Blizzard's own art","Square minimap with one button bar and an addon button drawer","Auto-hide for action bars, frames, buffs and the quest tracker","Nameplates: mana users, interrupt cue, range hint","Options inside Edit Mode, saved per layout","Midnight and WoW: Forever from one addon","140+ releases shipped by CI/CD"],links:[{label:"CurseForge",href:"https://www.curseforge.com/wow/addons/bolt",icon:"fa-download",style:"curseforge"},{label:"GitHub",href:"https://github.com/Yukisando/B.O.L.T",icon:"fa-github",secondary:!0}],fr:{alt:["Panneau d'options B.O.L.T dans World of Warcraft avec ses modules et r\xE9glages","Menu du jeu World of Warcraft revu, avec les raccourcis d'extension ajout\xE9s par B.O.L.T"],type:"Addon WoW",shortDescription:"Addon World of Warcraft modulaire qui redessine l'interface de Blizzard avec ses propres graphismes, pour Midnight et WoW: Forever",description:"B.O.L.T (Brittle and Occasionally Lethal Tweaks) rend l'interface de World of Warcraft plus nette sans la remplacer : de petits modules redessinent les cadres de Blizzard avec les graphismes de Blizzard. Cadres d'unit\xE9 sans portrait, minimap carr\xE9e avec une seule barre de boutons, barres qui s'effacent jusqu'au besoin, barres de nom qui signalent les lanceurs \xE0 mana et les sorts interruptibles. Chaque module s'active seul et se r\xE8gle dans le mode \xC9dition, sur Midnight et sur WoW: Forever.",features:["Menu de jeu enrichi (quitter le groupe, recharger l'UI, outils de groupe)","Cadres d'unit\xE9 et barres d'incantation sans portrait, graphismes Blizzard","Minimap carr\xE9e, une seule barre de boutons et un tiroir pour les boutons d'addons","Barres d'action, cadres, buffs et suivi de qu\xEAtes masqu\xE9s jusqu'au besoin","Barres de nom : lanceurs \xE0 mana, sorts interruptibles, port\xE9e","Options dans le mode \xC9dition, enregistr\xE9es par disposition","Midnight et WoW: Forever avec un seul addon","Plus de 140 versions publi\xE9es via CI/CD"]}},{id:"coldsnap-utilities",category:"Open Source",type:"Unity Package",title:"ColdSnap Utilities",shortDescription:"Open-source Unity package: one-window builds for every platform, TestFlight upload, scene quick open and editor helpers",description:"The Unity package behind every ColdSnap game and kiosk. Platform Builder builds Windows, macOS, Android (APK and App Bundle), WebGL and iOS from one window with saved scene lists, and sends iOS builds to TestFlight from a Windows PC through a macOS runner. Around it: scene quick open, a commit-and-push window, a one-click update check, pivot tools, dark title bars on Windows, a fullscreen WebGL kiosk template and a few runtime helpers. Installs from Git in the Package Manager; versions bump themselves from commit titles.",icon:"\u{1F6E0}\uFE0F",thumbnail:"/assets/projects/coldsnap-utilities/utilities-1-thumb.webp?v=20261110c",media:["/assets/projects/coldsnap-utilities/utilities-hero.jpg","/assets/projects/coldsnap-utilities/utilities-2.png","/assets/projects/coldsnap-utilities/utilities-3.png","/assets/projects/coldsnap-utilities/utilities-4.png","/assets/projects/coldsnap-utilities/utilities-5.jpg"],alt:["Collage of the ColdSnap Utilities windows in the Unity editor: Scene Quick Open, Git, Platform Builder","Platform Builder window: target platform, build options, app name and the scene list in build order","Scene Quick Open: every scene in the project with Open and add-to-scene buttons","Git window: branch, pending changes, commit message, Commit All + Push, Pull and a log","The Unity editor in dark mode, with ColdSnap's dark title bar and menu bar on Windows"],tech:["Unity","C#","UPM"],features:["Platform Builder: Windows, macOS, Android, WebGL and iOS from one window","Send to TestFlight from Windows (signed on a macOS runner)","Scene quick open, Git commit-and-push window, update check","Pivot tools, Auto Group, teleport player to the Scene camera","WebGL kiosk template and kiosk setup scripts","Automatic semantic versioning from commit titles"],links:[{label:"GitHub",href:"https://github.com/Yukisando/com.coldsnap.utilities",icon:"fa-github"}],fr:{alt:["Collage des fen\xEAtres ColdSnap Utilities dans l'\xE9diteur Unity : Scene Quick Open, Git, Platform Builder","Fen\xEAtre Platform Builder : plateforme cible, options de build, nom de l'app et liste des sc\xE8nes dans l'ordre du build","Scene Quick Open : toutes les sc\xE8nes du projet avec boutons Ouvrir et Ajouter","Fen\xEAtre Git : branche, changements en attente, message de commit, Commit All + Push, Pull et journal","L'\xE9diteur Unity en mode sombre, avec la barre de titre et la barre de menus sombres de ColdSnap sous Windows"],type:"Package Unity",shortDescription:"Package Unity open source : builds de toutes les plateformes depuis une fen\xEAtre, envoi TestFlight, ouverture rapide des sc\xE8nes",description:"Le package Unity derri\xE8re chaque jeu et borne ColdSnap. Platform Builder compile pour Windows, macOS, Android (APK et App Bundle), WebGL et iOS depuis une seule fen\xEAtre avec des listes de sc\xE8nes enregistr\xE9es, et envoie les builds iOS sur TestFlight depuis un PC Windows via un runner macOS. Autour : ouverture rapide des sc\xE8nes, fen\xEAtre de commit et push, v\xE9rification des mises \xE0 jour en un clic, outils de pivot, barres de titre sombres sous Windows, mod\xE8le WebGL plein \xE9cran pour bornes et quelques aides runtime. S'installe depuis Git dans le Package Manager ; les versions montent toutes seules d'apr\xE8s les titres de commit.",features:["Platform Builder : Windows, macOS, Android, WebGL et iOS depuis une fen\xEAtre","Envoi sur TestFlight depuis Windows (sign\xE9 sur un runner macOS)","Ouverture rapide des sc\xE8nes, fen\xEAtre Git commit et push, mises \xE0 jour","Outils de pivot, Auto Group, t\xE9l\xE9portation du joueur vers la cam\xE9ra","Mod\xE8le WebGL pour bornes et scripts d'installation kiosque","Versionnage s\xE9mantique automatique d'apr\xE8s les commits"]}},{id:"cooldown",category:"Open Source",type:"Typeface",title:"Cooldown Sans",playground:"/lab/cooldown/",shortDescription:"The typeface we built for all our projects, so that everyone can read them: dyslexic readers, people with low vision, children",description:`We use Cooldown Sans by default in all our projects. We make serious games, museum exhibits and learning tools, and the people who play them include children, dyslexic readers and people with low vision, so we built a typeface for them.

Dyslexia: d and q can end in a rounded tail, so they are never b and p turned around, and letters sit a little further apart.

Low vision: the height of the lowercase letters adjusts, for small text and for kiosk screens read from a few steps away.

For fun: each letter can tilt its own way, as if written by hand, and dots can turn into little snowflakes, because a game should look like one.`,icon:"\u2744",thumbnail:"/assets/projects/cooldown/cooldown-1-thumb.webp?v=20261120b",media:["/assets/projects/cooldown/cooldown-1.png"],alt:["The words Cooldown Sans with a snowflake, the letters b d p q with tails on d and q, Aa with taller lowercase letters, the word wobble with tilted letters, and weights from 300 to 700"],features:["Tails on d and q (stylistic set ss03), so b, d, p and q never mirror each other","Adjustable lowercase height for small text and screens read from a distance","Wobble axis: each letter tilts its own way, as if written by hand","Weights 300 to 700, snowflake dots (ss02) and a snowflake glyph","Used on every ColdSnap game, app and exhibit"],links:[{label:"GitHub",href:"https://github.com/Yukisando/cooldown-font",icon:"fa-github"}],fr:{alt:["Les mots Cooldown Sans avec un flocon, les lettres b d p q avec des queues sur d et q, Aa avec des minuscules plus hautes, le mot wobble aux lettres pench\xE9es, et les graisses de 300 \xE0 700"],type:"Police de caract\xE8res",shortDescription:"La police que nous avons cr\xE9\xE9e pour tous nos projets, pour que chacun puisse les lire : lecteurs dyslexiques, malvoyants, enfants",description:`Nous utilisons Cooldown Sans par d\xE9faut dans tous nos projets. Nous faisons des serious games, des installations de mus\xE9e et des outils p\xE9dagogiques, et parmi celles et ceux qui y jouent il y a des enfants, des lecteurs dyslexiques et des personnes malvoyantes : nous avons donc construit une police pour eux.

Dyslexie : d et q peuvent se terminer par une queue arrondie, pour ne jamais \xEAtre un b ou un p retourn\xE9, et les lettres sont un peu plus espac\xE9es.

Basse vision : la hauteur des minuscules se r\xE8gle, pour les petits textes et les \xE9crans de bornes lus \xE0 quelques pas.

Pour jouer : chaque lettre peut pencher \xE0 sa fa\xE7on, comme \xE9crite \xE0 la main, et les points peuvent devenir de petits flocons, parce qu'un jeu doit en avoir l'air.`,features:["Queues sur d et q (jeu stylistique ss03) : b, d, p et q ne se ressemblent plus en miroir","Hauteur des minuscules r\xE9glable pour les petits textes et les \xE9crans lus de loin","Axe \xAB bancal \xBB : chaque lettre penche \xE0 sa fa\xE7on, comme \xE9crite \xE0 la main","Graisses de 300 \xE0 700, points en flocon (ss02) et un flocon","Utilis\xE9e dans tous les jeux, apps et installations ColdSnap"]}}].filter(e=>!e.hidden);typeof module<"u"&&module.exports&&(module.exports=COLDSNAP_PROJECTS);
